'use strict';
// Standalone presentation: deliberately no Home Assistant client or network API.
const STORE = 'home-pulse-public-demo-v1';
const paths={home:'M3 11 12 3l9 8v10h-6v-7H9v7H3z',rooms:'M3 10 12 3l9 7v11H3z M9 21V12h6v9',energy:'m13 2-9 12h7l-1 8L21 9h-8z',climate:'M10 14V5a2 2 0 0 1 4 0v9a5 5 0 1 1-4 0 M12 9v9',heat:'M12 2c2 6-4 6-1 11 1-3 4-3 4-6 6 7 6 15-3 15C3 22 3 14 7 9c-1 5 2 6 2 6',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z',automation:'M12 9V3 M5 18l5-6 M19 18l-5-6 M9 3h6 M3 21h4v-4H3z M17 21h4v-4h-4z M9 9h6v4H9z',bins:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',f1:'M5 22V3h14v11H5 M5 3l5 5 5-5 4 5-4 6-5-6-5 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1z',bulb:'M9 18h6 M9 21h6 M8 14a7 7 0 1 1 8 0l-1 3H9z',washer:'M4 3h16v19H4z M7 6h1 M11 6h6 M7 14a5 5 0 1 0 10 0 5 5 0 0 0-10 0 M8 14q4 4 8 0',printer:'M5 8V3h14v5 M3 8h18v11H3z M7 19v3h10v-3 M8 12h8v5H8z',cat:'M4 9V3l6 4h4l6-4v6a9 9 0 1 1-16 0 M8 12h1 M15 12h1 M10 16l2 1 2-1',drop:'M12 2S4 12 4 16a8 8 0 0 0 16 0c0-4-8-14-8-14',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',check:'m5 12 4 4L19 6',window:'M4 3h16v18H4z M12 3v18 M4 12h16',power:'M12 2v10 M6 5a9 9 0 1 0 12 0',media:'M4 4h16v13H4z M8 21h8 M12 17v4 M10 8l5 3-5 3z',plus:'M12 4v16 M4 12h16'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.home}"/></svg>`;
const text={pl:{home:'Dom',rooms:'Pokoje',energy:'Energia',climate:'Klimat',heat:'Ogrzewanie',shield:'Ochrona',automation:'Automatyzacje',bins:'Kosze',f1:'F1',settings:'Ustawienia',sample:'dane przykładowe',welcome:'Dzień dobry',our:'Nasz dom',calm:'Dom jest spokojny, bezpieczny i komfortowy.',all:'Wszystkie pokoje',on:'Włączone',off:'Wyłączone',lights:'Światła',target:'Temperatura zadana',humidity:'Wilgotność',temp:'Temperatura',close:'Zamknięte',details:'Szczegóły',today:'dziś',back:'Powrót',device:'To urządzenie',reset:'Demo przywrócone do stanu początkowego.',local:'Interaktywne demo · dane i sterowanie są symulowane. Bez połączenia z Home Assistant.',room:'Pokój',saved:'Zapisano wyłącznie w tym demo.'},en:{home:'Home',rooms:'Rooms',energy:'Energy',climate:'Climate',heat:'Heating',shield:'Protection',automation:'Automations',bins:'Bins',f1:'F1',settings:'Settings',sample:'sample data',welcome:'Good morning',our:'Our home',calm:'Your home is calm, safe and comfortable.',all:'All rooms',on:'On',off:'Off',lights:'Lights',target:'Target temperature',humidity:'Humidity',temp:'Temperature',close:'Closed',details:'Details',today:'today',back:'Back',device:'This device',reset:'Demo restored to its initial state.',local:'Interactive demo · simulated data and controls. No connection to Home Assistant.',room:'Room',saved:'Saved only in this demo.'}};
const defaults=()=>({theme:'dark',style:'classic',glow:'none',color:'cyan',lang:'pl',reduce:false,roomView:'glass',security:'home',heating:'auto',rooms:[{id:'living',name:'Salon',en:'Living room',photo:'salon',temp:22.3,target:22,humidity:46,lights:[true,true,false],labels:['LED sufit','Lampa podłogowa','Oświetlenie TV'],kind:'bulb',media:true},{id:'kitchen',name:'Kuchnia',en:'Kitchen',photo:'kuchnia',temp:22.8,target:22,humidity:48,lights:[true,false,false],labels:['Światło główne','LED blat','Wyspa'],kind:'bulb',floor:true},{id:'bedroom',name:'Sypialnia',en:'Bedroom',photo:'sypialnia',temp:20.7,target:21,humidity:45,lights:[false,false],labels:['Światło główne','Lampki nocne'],kind:'bulb',ac:true},{id:'kids',name:'Pokój dziecka',en:'Child’s room',photo:'child-bedroom',temp:21.8,target:22,humidity:47,lights:[true,false],labels:['Światło główne','LED biurko'],kind:'bulb',ac:true},{id:'bathroom',name:'Łazienka',en:'Bathroom',photo:'lazienka',temp:23.2,target:23,humidity:52,lights:[false,false],labels:['Światło główne','Lustro'],kind:'bulb'},{id:'hall',name:'Korytarz',en:'Hallway',photo:'korytarz',temp:21.5,target:21,humidity:44,lights:[false],labels:['Światło główne'],kind:'bulb'},{id:'laundry',name:'Pralnia',en:'Laundry',photo:'pralnia',temp:22.1,target:21,humidity:51,lights:[false],labels:['Światło główne'],kind:'washer',running:true},{id:'workshop',name:'Warsztat',en:'Workshop',photo:'drukarka',temp:21.4,target:21,humidity:43,lights:[true],labels:['Lampka biurka'],kind:'printer',running:true},{id:'cats',name:'Kocia strefa',en:'Cat area',photo:'kocia-strefa',temp:21.9,target:21,humidity:45,lights:[false],labels:['Światło główne'],kind:'cat'}],automations:[true,true,true,true,true,true,false,true]});
let state;try{state=JSON.parse(localStorage.getItem(STORE))}catch{}if(!state||!Array.isArray(state.rooms)||!state.rooms.length)state=defaults();
let route='home',roomId='',toastTimer,filter='',pending=new Set(),acRooms=new Set();
const t=k=>text[state.lang]?.[k]||text.pl[k]||k;
const loc=(pl,en)=>state.lang==='en'?en:pl;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=r=>escapeHTML(state.lang==='en'?(r.en||r.name):r.name);
const fmt=n=>Number(n).toLocaleString(state.lang==='pl'?'pl-PL':'en-GB',{minimumFractionDigits:1,maximumFractionDigits:1});
const light=()=>state.theme==='light'||state.theme==='auto'&&new Date().getHours()>=7&&new Date().getHours()<19;
const asset=(name,category='rooms')=>`assets/${state.style==='cartoon'?'cartoon':category}/${name}.webp`;
const roomImage=r=>asset(r.photo+(light()?'-day':''));
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(state))}catch{toast(loc('Pamięć przeglądarki jest wyłączona. Zmiany działają do odświeżenia.','Browser storage is disabled. Changes last until refresh.'))}};
const toast=message=>{const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)};
const btn=(label,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const orb=(symbol,cls='')=>`<span class="orb ${cls}">${icon(symbol)}</span>`;
const toggle=(active,action,label)=>`<button class="toggle" data-action="${action}" aria-label="${escapeHTML(label)}" aria-pressed="${!!active}"></button>`;
const selected=(key,options)=>`<div class="segmented">${options.map(([v,l])=>btn(l,`pref:${key}:${v}`,state[key]===v?'selected':'',`aria-pressed="${state[key]===v}"`)).join('')}</div>`;
const head=(title,subtitle)=>`<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><span class="demo-badge">${loc('Dane demonstracyjne','Sample data')}</span></div>`;
const sumLights=()=>state.rooms.reduce((a,r)=>a+r.lights.filter(Boolean).length,0);
const roomStatus=r=>r.running?loc(r.kind==='washer'?'Pralka pracuje · 0:42':'Druk w toku · 62%',r.kind==='washer'?'Washing · 0:42':'Printing · 62%'):r.lights.some(Boolean)?`${r.lights.filter(Boolean).length} ${loc(r.lights.filter(Boolean).length===1?'światło':'światła','lights')} · ${fmt(r.temp)}°C`:`${loc('Zgaszone','Lights off')} · ${fmt(r.temp)}°C`;
function roomCard(r){return `<a class="room-card" href="#rooms/${r.id}" aria-label="${name(r)} — ${escapeHTML(roomStatus(r))}"><img src="${roomImage(r)}" alt="${name(r)}" loading="lazy">${orb(r.kind,r.running?'aqua':r.lights.some(Boolean)?'on':'')}<span class="room-temp">${fmt(r.temp)}°</span><div class="room-caption"><h3>${name(r)}</h3><small>${escapeHTML(roomStatus(r))}</small></div></a>`}
function flow(){return `<div class="energy-flow"><div class="flow-sources"><div class="row">${orb('energy','on flow-dot')}<div><strong>486 W&nbsp; £1.42</strong><small class="muted">${loc('Prąd · dziś 4,2 kWh','Electricity · today 4.2 kWh')}</small></div></div><div class="row">${orb('heat','heat')}<div><strong>8.1 kWh&nbsp; £0.78</strong><small class="muted">${loc('Gaz · dziś 0,72 m³','Gas · today 0.72 m³')}</small></div></div></div><div class="cost-ring"><strong>£2.20</strong><small>${t('today')}</small></div><div><strong class="gold">24.8 p</strong><small class="muted">${loc('za kWh teraz','per kWh now')}</small><p class="teal">● ${loc('średnio','average')}</p><small>${loc('dalej','next')} 22.1 p</small></div></div><div class="water">${icon('drop')}<strong>${loc('Woda','Water')}</strong><small>${loc('Dzisiejszy odczyt','Today’s reading')}</small><strong style="margin-left:auto">168 L</strong></div>`}
function pulse(){let lines='';for(let i=0;i<40;i++){let d='';for(let j=0;j<=180;j++){const a=j/180*Math.PI*2,r=201+18*Math.sin(a*3+i*.09)+i*.25;d+=`${j?'L':'M'}${(250+Math.cos(a)*r).toFixed(2)},${(250+Math.sin(a)*r).toFixed(2)}`}lines+=`<path d="${d}Z" stroke="${i<20?'#e9b85d':'#3dbba8'}" opacity="${.13+i%5*.05}"/>`}
return `<section class="pulse" aria-label="${loc('Puls domu','House pulse')}"><svg class="ring" viewBox="0 0 500 500" aria-hidden="true"><g class="pulse-breathe">${lines}</g><g class="pulse-breathe reverse" stroke="var(--gold)" opacity=".5"><ellipse cx="250" cy="250" rx="210" ry="201" transform="rotate(30 250 250)"/></g></svg><div class="pulse-center"><span class="house-icon">${icon('home')}</span><h2>Home Pulse</h2><a href="#shield" class="teal">● ${loc('Wszystko w porządku','Everything is fine')}</a><p><small>${loc('Czujniki dostępne · okna zamknięte','Sensors online · windows closed')}</small></p><div class="row metrics">${[['bulb',`${sumLights()} ${loc('wł.','on')}`],['climate','22.1°C'],['energy','486 W'],['shield',(state.security==='off'?t('off'):loc('Chroniony','Protected'))]].map(([i,l])=>`<div class="metric">${orb(i,i==='bulb'?'on':'')}<strong>${l}</strong></div>`).join('')}</div></div></section>`}
function home(){return `<div class="home-top"><div class="home-left"><section class="welcome"><p class="eyebrow">${t('our')}</p><h1>${t('welcome')}</h1><p>${t('calm')}</p><a class="pill" href="#bins">${icon('bins')} ${loc('Kosze jutro · wystaw dziś wieczorem','Bins tomorrow · put them out tonight')}</a><br><a class="pill" href="#f1">${icon('f1')} ${loc('Grand Prix · przykładowy weekend','Grand Prix · sample race weekend')}</a></section><section class="panel weather"><img src="${asset(light()?'clear-day-light':'dusk-partlycloudy','weather')}" alt="${loc('Panorama miasta','City skyline')}"><div class="weather-copy"><div class="big">17°C</div><strong>${loc('Częściowe zachmurzenie','Partly cloudy')}</strong><p><small>${loc('Odczuwalna 16° · wiatr 9 km/h','Feels like 16° · wind 9 km/h')}</small></p></div><div class="forecast">${[loc('Dziś wieczór','Tonight'),loc('Jutro','Tomorrow'),loc('Piątek','Friday')].map((x,i)=>`<div><small>${x}</small><br>${i===0?'☾':'☁'} &nbsp;${[12,18,16][i]}°</div>`).join('')}</div></section></div>${pulse()}<div class="home-right"><section class="panel"><div class="row between" style="margin-bottom:18px"><h2 style="margin:0">${loc('Przepływ energii','Energy flow')}</h2><small class="teal">● ${loc('Symulacja','Simulation')}</small></div>${flow()}</section><div class="home-right-bottom"><section class="panel"><div class="row between"><h2 style="margin:0">${t('climate')}</h2><small>${loc('Cały dom','Whole home')}</small></div><a class="temp-readout" href="#climate"><div class="thermo-bar"></div><div><div class="big">22.1°</div><p class="gold">${loc('Cel 22,0°C','Target 22.0°C')}</p><small>${loc('Utrzymuje temperaturę','Maintaining temperature')}</small></div></a><a class="pill" href="#heat">${icon('heat')} ${loc('Ogrzewanie automatyczne','Automatic heating')}</a></section><section class="panel"><h2>${loc('Ostatnio w domu','Recently at home')}</h2><div class="tiny-log">${[['10:24',loc('Pralka rozpoczęła cykl','Washing cycle started')],['09:00',loc('Podajnik: karmienie poranne','Feeder: morning meal')],['08:35',loc('Światło w kuchni','Kitchen lighting')]].map(([x,y])=>`<div><time>${x}</time><span>${y}<br><small>${loc('uruchomiono','triggered')}</small></span></div>`).join('')}</div></section></div></div></div><div class="section-title"><h2 class="row">${icon('rooms')}${t('rooms')}</h2><a class="pill" href="#rooms">${t('all')}${icon('arrow')}</a></div><div class="room-strip">${state.rooms.slice(0,5).map(roomCard).join('')}</div>`}
function roomPage(r){const isAC=acRooms.has(r.id),key=`light:${r.id}:0`;return `<div class="page-head"><a class="row" href="#rooms">${icon('back')}${t('rooms')}</a><span class="demo-badge">${loc('Sterowanie symulowane','Simulated controls')}</span></div><div class="room-hero"><img src="${roomImage(r)}" alt="${name(r)}"><div class="room-hero-copy"><div><h1>${name(r)}</h1><p>${fmt(r.temp)}°C &nbsp; · &nbsp; ${r.humidity}% &nbsp; · &nbsp; ${t('close')}</p></div>${btn(`${icon('bulb')} ${escapeHTML(loc(r.labels[0],'Main light'))} · ${pending.has(key)?loc('ustawiam…','updating…'):r.lights[0]?t('on'):t('off')}`,key,'row')}</div></div><div class="room-controls"><section class="panel"><h2 class="row">${orb('bulb',r.lights.some(Boolean)?'on':'')}${t('lights')} <small>${r.lights.filter(Boolean).length}/${r.lights.length}</small></h2>${r.lights.map((v,i)=>`<div class="control-line"><div><strong>${escapeHTML(loc(r.labels[i],i===0?'Main light':`Light ${i+1}`))}</strong><small class="${pending.has(`light:${r.id}:${i}`)?'pending':''}">${pending.has(`light:${r.id}:${i}`)?loc('Ustawiam w symulacji…','Updating simulation…'):v?t('on'):t('off')}</small></div>${toggle(v,`light:${r.id}:${i}`,loc('Przełącz światło','Toggle light'))}</div>`).join('')}<label><small>${loc('Jasność głównego światła','Main light brightness')} <output id="brightness-value">${r.brightness||75}%</output></small><input data-room="${r.id}" id="brightness" type="range" min="5" max="100" value="${r.brightness||75}" aria-label="${loc('Jasność','Brightness')}"></label></section><section class="panel"><h2>${t('climate')}</h2>${r.ac||r.floor?`<div class="segmented">${btn(loc(r.floor?'Podłogowe':'Grzejnik','Heating'),`climate-kind:${r.id}:heat`,!isAC?'selected':'')}${btn(loc(r.floor?'Termostat':'Klimatyzacja',r.floor?'Thermostat':'Air conditioning'),`climate-kind:${r.id}:ac`,isAC?'selected':'')}</div>`:''}<div class="dial"><small>${isAC?loc('Klimatyzacja','Air conditioning'):t('target')}</small><strong>${fmt(isAC?(r.acTarget||21):r.target)}°</strong><small>${loc('Teraz','Now')} ${fmt(r.temp)}°</small></div><div class="stepper">${btn('−',`temp:${r.id}:-0.5`,'',`aria-label="${loc('Zmniejsz temperaturę','Decrease temperature')}"`)}<small>${t('target')}</small>${btn('+',`temp:${r.id}:0.5`,'',`aria-label="${loc('Zwiększ temperaturę','Increase temperature')}"`)}</div><div class="note">${loc('Przyciski zmieniają tylko dane demonstracyjne.','Buttons change demonstration data only.')}</div>${isAC?`<div class="control-line"><span>${loc('Tryb','Mode')}</span><select data-field="acMode" data-room="${r.id}" aria-label="${loc('Tryb klimatyzacji','AC mode')}">${['Auto','Cool','Heat','Dry','Fan'].map(m=>`<option ${r.acMode===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="control-line"><span>${loc('Wentylator','Fan speed')}</span><select data-field="fan" data-room="${r.id}" aria-label="${loc('Prędkość wentylatora','Fan speed')}">${['Auto','Low','Medium','High'].map(m=>`<option ${r.fan===m?'selected':''}>${m}</option>`).join('')}</select></div>`:''}</section><section class="panel"><h2>${loc('W pokoju','In this room')}</h2><div class="control-line"><span>${t('temp')}</span><strong>${fmt(r.temp)}°C</strong></div><div class="control-line"><span>${t('humidity')}</span><strong>${r.humidity}%</strong></div><div class="control-line"><span>${loc('Okna','Windows')}</span><strong class="teal">${t('close')}</strong></div>${r.media?`<div class="control-line"><span>${loc('Telewizor','TV')}</span>${toggle(r.tv,`media:${r.id}`,loc('Przełącz telewizor w demo','Toggle demo TV'))}</div>`:''}${r.kind==='washer'||r.kind==='printer'?`<div class="control-line"><span>${loc('Praca urządzenia','Device activity')}</span>${toggle(r.running,`running:${r.id}`,loc('Symuluj pracę','Simulate activity'))}</div>`:''}${r.kind==='cat'?`<div class="note">${loc('Kuweta gotowa · pojemnik 18% · karmnik dostępny','Litter box ready · bin 18% · feeder online')}</div>`:''}<p style="margin-top:20px"><small>${loc('Przykładowe odczyty, nie dane prawdziwego domu.','Sample readings, not real household data.')}</small></p></section></div><nav class="filmstrip" aria-label="${t('rooms')}">${state.rooms.map(x=>`<a href="#rooms/${x.id}" class="${x.id===r.id?'active':''}" ${x.id===r.id?'aria-current="page"':''}><img src="${roomImage(x)}" alt=""><span>${name(x)}</span></a>`).join('')}</nav>`}
function climate(){return head(t('climate'),loc('Temperatura, wilgotność i komfort w każdym pokoju.','Temperature, humidity and comfort in every room.'))+`<div class="energy-stats"><section class="panel stat"><p>${loc('Średnia w domu','Home average')}</p><div class="big">22.1°C</div></section><section class="panel stat"><p>${loc('Wilgotność','Humidity')}</p><div class="big">47%</div></section><section class="panel stat"><p>${loc('Okna','Windows')}</p><div class="big">${loc('Zamknięte','Closed')}</div></section></div><div class="climate-grid">${state.rooms.map(r=>`<a class="panel climate-card" href="#rooms/${r.id}"><div class="row between"><h3>${name(r)}</h3>${icon('climate')}</div><div class="big">${fmt(r.temp)}°<small>${loc('Cel','Target')} ${fmt(r.target)}°</small></div><div class="row between"><small>${t('humidity')} ${r.humidity}%</small><small class="teal">● ${loc('Komfort','Comfort')}</small></div></a>`).join('')}</div>`}
function energy(){return head(t('energy'),loc('Prąd, gaz i woda. Osobno zużycie, osobno koszty.','Electricity, gas and water. Clear usage and costs.'))+`<div class="energy-stats">${[[loc('Prąd dzisiaj','Electricity today'),'4.2 kWh','£1.42'],[loc('Gaz dzisiaj','Gas today'),'8.1 kWh','£0.78'],[loc('Woda dzisiaj','Water today'),'168 L','£0.42']].map(([a,b,c])=>`<section class="panel stat"><p>${a}</p><div class="big">${b}</div><strong class="gold">${c}</strong></section>`).join('')}</div><div class="columns-2"><section class="panel"><h2>${loc('Przepływ energii','Energy flow')}</h2>${flow()}<div class="note">${loc('Dane są przykładowe. Właściwy dashboard korzysta z czujników skonfigurowanych w HA.','These are sample values. The real dashboard uses configured HA sensors.')}</div></section><section class="panel"><h2>${loc('Koszt dnia','Daily cost')}</h2><div class="big gold">£2.20</div><p>${loc('Prąd i gaz · woda liczona osobno','Electricity and gas · water shown separately')}</p><div class="control-line"><span>${loc('Prąd','Electricity')}</span><strong>£1.42</strong></div><div class="control-line"><span>${loc('Gaz','Gas')}</span><strong>£0.78</strong></div></section></div><section class="panel" style="margin-top:20px"><div class="row between"><h2>${loc('Przykładowe ceny godzinowe','Sample hourly prices')}</h2><span class="pill">p / kWh</span></div><p>${loc('Profil przykładowy, nie bieżąca taryfa ani rekomendacja.','Illustrative profile, not a live tariff or recommendation.')}</p><div class="bars">${[18,16,13,11,12,15,20,24,29,31,28,26,24,22,25,32,38,41,36,30,26,24,21,19].map((v,i)=>`<div class="bar ${v>29?'expensive':''}" style="height:${v/44*100}%" title="${i}:00 · ${v}p/kWh"></div>`).join('')}</div><div class="axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div></section>`}
function heating(){return head(t('heat'),loc('Źródło ciepła i temperatury zadane w pokojach.','Heat source and room temperature targets.'))+`<div class="boiler-layout"><section class="panel boiler-visual"><img src="${asset(light()?'boiler-light':'boiler','heating')}" alt="${loc('Kocioł gazowy','Gas boiler')}"><div class="boiler-status"><span class="gold">●</span> ${loc('Gotowy','Ready')+' · '+({auto:'Auto',comfort:loc('Komfort','Comfort'),eco:'Eco',off:t('off')}[state.heating])}</div></section><div class="stack"><section class="panel"><h2>${loc('Tryb domu','Home mode')}</h2>${selected('heating',[['auto','Auto'],['comfort',loc('Komfort','Comfort')],['eco','Eco'],['off',t('off')]])}<div class="control-line"><span>${loc('Zasilanie','Flow temperature')}</span><strong>48.2°C</strong></div><div class="control-line"><span>${loc('Powrót','Return temperature')}</span><strong>39.6°C</strong></div><div class="control-line"><span>${loc('Ciśnienie','Pressure')}</span><strong>1.4 bar</strong></div><small>${loc('Odczyty demonstracyjne. Kocioł nie jest połączony.','Demonstration readings. No boiler is connected.')}</small></section><section class="panel"><h2>${t('rooms')}</h2>${state.rooms.slice(0,5).map(r=>`<div class="control-line"><a href="#rooms/${r.id}">${name(r)}<small>${loc('Teraz','Now')} ${fmt(r.temp)}°</small></a><div class="row">${btn('−',`temp:${r.id}:-0.5`,'round',`aria-label="${name(r)} ${loc('zmniejsz','decrease')}"`)}<strong>${fmt(r.target)}°</strong>${btn('+',`temp:${r.id}:0.5`,'round',`aria-label="${name(r)} ${loc('zwiększ','increase')}"`)}</div></div>`).join('')}</section></div></div>`}
function protection(){return head(t('shield'),loc('Stan ochrony, czujniki i okna. Bez obrazu z kamer.','Protection status, sensors and windows. No camera feeds.'))+`<section class="panel" style="margin-bottom:20px"><div class="row">${orb('shield','on')}<div><h2 style="margin:0">${loc('Wszystko w porządku','Everything is fine')}</h2><p>${loc('Wszystkie przykładowe czujniki dostępne.','All sample sensors are online.')}</p></div></div></section><div class="columns-2"><section class="panel"><h2>${loc('Tryb ochrony','Protection mode')}</h2>${selected('security',[['home',loc('W domu','Home')],['away',loc('Poza domem','Away')],['schedule',loc('Harmonogram','Schedule')],['off',t('off')]])}<div class="note">${loc('Zmiana tutaj jest wyłącznie symulacją. Nie steruje alarmem.','Changes here are simulated. No alarm is controlled.')}</div></section><section class="panel"><h2>${loc('Ochrona alarmowa','Safety automations')}</h2><div class="row"><span class="big teal">5/5</span><p>${loc('Aktywne · czad i wycieki','Enabled · CO and water leaks')}</p></div></section></div><div class="sensor-grid" style="margin-top:20px">${[['window',loc('Okna','Windows'),loc('Wszystkie zamknięte','All closed')],['automation',loc('Ruch','Motion'),loc('Brak ruchu','No motion')],['drop',loc('Zalanie','Water leaks'),loc('Nie wykryto','None detected')],['shield',loc('Czad','Carbon monoxide'),loc('W normie','Normal')]].map(([i,a,b])=>`<section class="panel sensor">${orb(i,'aqua')}<h3>${a}</h3><p>${b}</p></section>`).join('')}</div>`}
const autoNames=()=>[loc('Kuchnia · światło po zmroku','Kitchen · lighting after dusk'),loc('Łazienka · wentylacja','Bathroom · ventilation'),loc('Koty · karmienie poranne','Cats · morning feeding'),loc('Pralka · koniec cyklu','Laundry · end of cycle'),loc('Ogrzewanie · tryb nocny','Heating · night mode'),loc('Ochrona · wykrycie wycieku','Protection · leak detection'),loc('Salon · stare oświetlenie','Living room · old lighting rule'),loc('Tani prąd · przypomnienie','Cheap electricity · reminder')];
function automations(){const names=autoNames();return head(t('automation'),loc('Co dom robi sam. Przykładowa historia i reguły.','What your home does for you. Sample history and rules.'))+`<div class="columns-2"><section class="panel"><h2>${loc('Dziś w domu','Today at home')}</h2><div class="timeline">${[['10:24',names[3]],['09:00',names[2]],['08:35',names[0]],['07:00',names[4]]].map(([x,y])=>`<div><time>${x}</time><section><h3>${y}</h3><p>${loc('Uruchomiono · wpis demonstracyjny','Triggered · demonstration entry')}</p></section></div>`).join('')}</div></section><section class="panel"><h2>${loc('Automatyzacje','Automations')} · ${state.automations.filter(Boolean).length}/${names.length}</h2><input class="auto-filter" id="auto-search" type="text" value="${escapeHTML(filter)}" placeholder="${loc('Szukaj automatyzacji…','Search automations…')}" aria-label="${loc('Szukaj automatyzacji','Search automations')}"><div id="auto-list">${autoList()}</div></section></div>`}
function autoList(){return autoNames().map((n,i)=>({n,i})).filter(({n})=>n.toLocaleLowerCase().includes(filter.toLocaleLowerCase())).map(({n,i})=>`<div class="control-line"><div><strong>${n}</strong><small>${state.automations[i]?loc('Włączona','Enabled'):loc('Wyłączona','Disabled')}</small></div>${toggle(state.automations[i],`auto:${i}`,n)}</div>`).join('')||`<p>${loc('Brak wyników','No results')}</p>`}
function bins(){return head(t('bins'),loc('Najbliższy odbiór i kolory koszy. Harmonogram demonstracyjny.','Next collections and bin colours. Demonstration schedule.'))+`<div class="note">${loc('Wystaw kosze dziś wieczorem · odbiór jutro. Daty w demo liczone względem dzisiejszego dnia.','Put your bins out tonight · collection tomorrow. Demo dates are relative to today.')}</div><div class="bin-grid">${[[loc('Zmieszane','General waste'),'#9b9c9d',1],[loc('Ogrodowe','Garden waste'),'#b08152',1],[loc('Recykling','Recycling'),'#519cc9',8]].map(([n,c,d])=>`<section class="panel bin-card"><div class="bin-drawing" style="--bin:${c}">${icon('bins')}</div><h2 style="margin:0">${n}</h2><div class="big" style="font-size:28px">${d===1?loc('Jutro','Tomorrow'):loc('Za 8 dni','In 8 days')}</div><p>${future(d)}</p></section>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>${loc('Nadchodzące odbiory','Upcoming collections')}</h2>${[1,8,15,22].map((d,i)=>`<div class="control-line"><strong>${future(d)}</strong><span>${i%2?loc('Recykling','Recycling'):loc('Zmieszane + ogrodowe','General + garden waste')}</span></div>`).join('')}</section>`}
function future(n){const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString(state.lang==='pl'?'pl-PL':'en-GB',{weekday:'long',day:'numeric',month:'long'})}
function f1(){return head('Formula 1',loc('Wygląd zakładki F1 na przykładzie fikcyjnego weekendu.','F1 page preview using a fictional race weekend.'))+`<section class="panel f1-hero"><img src="${asset(light()?'f1-hero-day':'f1-hero','f1')}" alt="${loc('Anonimowy bolid na torze','Unbranded open-wheel racing car')}"><div class="f1-copy"><p class="eyebrow">${loc('Przykładowe Grand Prix','Sample Grand Prix')}</p><h1>Night Circuit</h1><p>${loc('Do wyścigu · odliczanie demonstracyjne','Until the race · demonstration countdown')}</p><div class="countdown">${[['02',loc('dni','days')],['14',loc('godzin','hours')],['36',loc('minut','minutes')]].map(([n,l])=>`<div><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><span class="pill">${loc('Przykład · nie aktualny kalendarz F1','Sample · not the current F1 calendar')}</span></div></section><div class="columns-2" style="margin-top:20px"><section class="panel"><h2>${loc('Weekend wyścigowy','Race weekend')}</h2>${[[loc('Piątek','Friday'),'14:00',loc('Trening 1','Practice 1')],[loc('Piątek','Friday'),'18:00',loc('Trening 2','Practice 2')],[loc('Sobota','Saturday'),'17:00',loc('Kwalifikacje','Qualifying')],[loc('Niedziela','Sunday'),'18:00',loc('Wyścig','Race')]].map(([d,h,n])=>`<div class="control-line"><span>${d}<small>${n}</small></span><strong class="gold">${h}</strong></div>`).join('')}</section><section class="panel" style="padding:0;overflow:hidden"><img src="${asset(light()?'f1-salon-day':'f1-salon','f1')}" alt="${loc('Wyścig na ekranie w salonie','Watching a race in the living room')}" style="width:100%;height:230px;object-fit:cover"><div style="padding:22px"><h2>${loc('Dom w trakcie wyścigu','Your home during the race')}</h2><p>${loc('Podgląd pomysłu: salon, telewizor i oświetlenie dopasowane do wyścigu. W demo niczego nie uruchamiamy.','A preview of a race-day setup: living room, TV and ambient lighting. No real devices are started.')}</p></div></section></div>`}
function settings(){return head(t('settings'),loc('Dopasuj wygląd i wypróbuj konfigurację przykładowego domu.','Personalise the appearance and try configuring a sample home.'))+`<div class="settings stack"><section class="panel"><h2>${t('device')}</h2><div class="setting-row"><div><h3>${loc('Język','Language')}</h3><p>${loc('Język interfejsu demonstracyjnego.','Demonstration interface language.')}</p></div>${selected('lang',[['pl','Polski'],['en','English']])}</div><div class="setting-row"><div><h3>${loc('Motyw','Theme')}</h3><p>${loc('Ciemny, jasny lub zgodny z lokalną porą dnia (7–19).','Dark, light or local daytime (07:00–19:00).')}</p></div>${selected('theme',[['dark',loc('Ciemny','Dark')],['light',loc('Jasny','Light')],['auto','Auto']])}</div><div class="setting-row"><div><h3>${loc('Styl','Style')}</h3><p>${loc('Klasyczny: realistyczne zdjęcia. Szklany: zdjęcia i bardziej przezroczyste panele. Cartoon: ilustracje zamiast zdjęć.','Classic: realistic photography. Glass: photography with translucent panels. Cartoon: storybook illustrations.')}</p></div>${selected('style',[['classic',loc('Klasyczny','Classic')],['glass',loc('Szklany','Glass')],['cartoon','Cartoon']])}</div><div class="setting-row"><div><h3>${loc('Podświetlenie','Ambient glow')}</h3><p>${loc('Kolorowa poświata wokół paneli.','Coloured glow around panels.')}</p></div>${selected('glow',[['none',loc('Brak','None')],['soft',loc('Subtelne','Subtle')],['strong',loc('Neon mocny','Strong neon')]])}</div><div class="setting-row"><div><h3>${loc('Kolor poświaty','Glow colour')}</h3></div><div class="swatches">${[['cyan','#26d7e1'],['pink','#e552ad'],['amber','#eeb45c'],['green','#64d08d']].map(([v,c])=>btn('',`pref:color:${v}`,`swatch ${state.color===v?'selected':''}`,`style="--swatch:${c}" aria-label="${v}" aria-pressed="${state.color===v}"`)).join('')}</div></div><div class="setting-row"><div><h3>${loc('Ogranicz ruch','Reduce motion')}</h3><p>${loc('Zatrzymuje pulsowanie i animacje. Respektuje też ustawienie systemowe.','Stops pulsing and motion. Also respects your system preference.')}</p></div>${toggle(state.reduce,'reduce',loc('Ogranicz ruch','Reduce motion'))}</div></section><section class="panel"><div class="row between"><h2 style="margin:0">${loc('Przykładowy dom','Sample home')}</h2>${btn(`+ ${loc('Dodaj pokój','Add room')}`,'add-room')}</div><div class="note">${loc('Ten edytor służy do demonstracji. Nie odczytuje obszarów ani urządzeń HA. Zmiany zostają tylko w tej przeglądarce.','This editor is a demonstration. It does not read HA areas or devices. Changes stay in this browser only.')}</div>${state.rooms.map(r=>`<div class="control-line"><span>${name(r)}<small>${r.lights.length} ${loc('świateł','lights')} · ${fmt(r.temp)}°C</small></span><div class="row">${btn(loc('Edytuj','Edit'),`edit:${r.id}`,'quiet')}${btn(loc('Usuń','Remove'),`remove:${r.id}`,'quiet',state.rooms.length===1?'disabled':'')}</div></div>`).join('')}</section><section class="panel"><h2>${loc('O demonstracji','About this demo')}</h2><p>${loc('To samodzielna prezentacja oparta na wyglądzie Home Pulse, nie paczka instalacyjna dashboardu. Wartości, harmonogramy i urządzenia są przykładowe.','This is a standalone presentation based on Home Pulse’s visual design, not an installable dashboard package. Values, schedules and devices are illustrative.')}</p><div class="note">${t('local')}</div>${btn('Reset demo','reset')}</section></div>`}
function applyLook(){document.body.className=[light()?'light':'',state.style==='glass'?'glass':'',state.reduce?'reduced':''].join(' ');document.documentElement.lang=state.lang;const colors={cyan:'38,215,225',pink:'229,82,173',amber:'238,180,92',green:'100,208,141'};const c=colors[state.color]||colors.cyan;document.body.style.setProperty('--neon',state.glow==='none'?'0 0 0 transparent':state.glow==='strong'?`0 0 25px rgba(${c},.27),inset 0 0 0 1px rgba(${c},.32)`:`0 0 14px rgba(${c},.12)`);document.querySelector('#theme-shortcut').innerHTML=icon(light()?'moon':'sun');document.querySelector('#theme-shortcut').ariaLabel=loc('Zmień motyw','Change theme');document.querySelector('[data-label="sample"]').textContent=t('sample');document.querySelector('#footer').innerHTML=`<span>${t('local')}</span><a href="../index.html">${loc('O projekcie','About the project')}</a>`}
function render(){applyLook();const nav=['home','rooms','energy','climate','heat','shield','automation','bins','f1','settings'];document.querySelector('#sidebar').innerHTML=`<a class="logo" href="#home" aria-label="Home Pulse">${icon('home')}</a>`+nav.map(n=>`<a class="nav ${route===n?'active':''}" href="#${n}" ${route===n?'aria-current="page"':''}>${icon(n)}<span>${t(n)}</span></a>`).join('');const main=document.querySelector('#main');const r=state.rooms.find(x=>x.id===roomId);main.innerHTML=route==='rooms'?(r?roomPage(r):head(t('rooms'),loc('Twój dom, pokój po pokoju. Otwórz kafelek i wypróbuj sterowanie.','Your home, room by room. Open a tile and try the controls.'))+`<div class="rooms-grid">${state.rooms.map(roomCard).join('')}</div>`):({home,energy,climate,heat:heating,shield:protection,automation:automations,bins,f1,settings}[route]||home)();document.title=`${t(route)} · Home Pulse demo`;document.querySelectorAll('[data-action^="light:"]').forEach(el=>{if(pending.has(el.dataset.action))el.disabled=true});}
function readRoute(){const [page,id]=location.hash.slice(1).split('/');route=['home','rooms','energy','climate','heat','shield','automation','bins','f1','settings'].includes(page)?page:'home';roomId=id||'';if(roomId&&!state.rooms.some(x=>x.id===roomId)){roomId='';history.replaceState(null,'','#rooms')}filter='';render();window.scrollTo({top:0,behavior:'instant'})}
function demoReset(){state=defaults();pending.clear();acRooms.clear();save();if(location.hash!=='#home')location.hash='home';else render();toast(t('reset'))}
function showEditor(id){const r=state.rooms.find(x=>x.id===id);const d=document.querySelector('#room-editor');d.dataset.id=id||'';d.dataset.photo=r?.photo||'sypialnia-2';d.innerHTML=`<div class="row between"><h2>${r?loc('Edytuj pokój','Edit room'):loc('Dodaj pokój','Add room')}</h2>${btn('×','close-editor','round',`aria-label="${loc('Zamknij','Close')}"`)}</div><label>${loc('Nazwa pokoju','Room name')}<input id="room-name" type="text" maxlength="40" value="${escapeHTML(r?.name||loc('Pokój gościnny','Guest room'))}"></label><p>${loc('Zdjęcie pokoju','Room photograph')}</p><div class="photo-picker">${['sypialnia-2','gabinet','garaz','salon','kuchnia','ogrod'].map(p=>btn(`<img src="${asset(p+(light()?'-day':''))}" alt="${p}">`,`photo:${p}`,p===d.dataset.photo?'selected':'',`aria-label="${p}"`)).join('')}</div><div class="note">${loc('Dodany pokój ma przykładowe światło i termostat. Nie tworzy encji w HA.','The room gets a sample light and thermostat. No HA entities are created.')}</div>${btn(loc('Zapisz w demo','Save in demo'),'save-room')} <small>${loc('Tylko pamięć tej przeglądarki','This browser only')}</small>`;d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,id,v]=b.dataset.action.split(':');if(a==='pref'){const allowed={theme:['dark','light','auto'],style:['classic','glass','cartoon'],glow:['none','soft','strong'],color:['cyan','pink','amber','green'],lang:['pl','en'],security:['home','away','schedule','off'],heating:['auto','comfort','eco','off']};if(allowed[id]?.includes(v)){state[id]=v;save();render();if(id==='security'||id==='heating')toast(loc('Zmieniono tylko stan demonstracyjny.','Demo state changed only.'))}return}if(a==='reset'){demoReset();return}if(a==='reduce'){state.reduce=!state.reduce;save();render();return}const r=state.rooms.find(x=>x.id===id);if(a==='light'&&r){const key=b.dataset.action;if(pending.has(key))return;pending.add(key);render();setTimeout(()=>{if(!pending.has(key))return;r.lights[+v]=!r.lights[+v];pending.delete(key);save();render();toast(loc('Potwierdzono w symulacji. Żadne urządzenie nie zostało przełączone.','Simulation confirmed. No real device was switched.'))},550)}if(a==='temp'&&r){if(acRooms.has(id))r.acTarget=Math.max(16,Math.min(30,(r.acTarget||21)+Number(v)));else r.target=Math.max(10,Math.min(30,r.target+Number(v)));save();render();toast(loc('Temperatura zmieniona tylko w demo.','Temperature changed only in the demo.'))}if(a==='climate-kind'){v==='ac'?acRooms.add(id):acRooms.delete(id);render()}if((a==='media'||a==='running')&&r){a==='media'?r.tv=!r.tv:r.running=!r.running;save();render();toast(loc('Zmieniono stan w symulacji.','Simulation state changed.'))}if(a==='auto'){state.automations[+id]=!state.automations[+id];save();render();toast(loc('Zmieniono tylko przykładową regułę.','Sample rule changed only.'))}if(a==='add-room')showEditor();if(a==='edit')showEditor(id);if(a==='close-editor')document.querySelector('#room-editor').close();if(a==='photo'){const d=document.querySelector('#room-editor');d.dataset.photo=id;d.querySelectorAll('[data-action^="photo:"]').forEach(x=>x.classList.toggle('selected',x===b))}if(a==='save-room'){const d=document.querySelector('#room-editor'),n=document.querySelector('#room-name').value.trim();if(!n){document.querySelector('#room-name').focus();return}const original=state.rooms.find(x=>x.id===d.dataset.id);if(original){original.name=n;original.en=n;original.photo=d.dataset.photo}else{const used=new Set(state.rooms.map(x=>x.id));let i=1;while(used.has(`demo-room-${i}`))i++;state.rooms.push({id:`demo-room-${i}`,name:n,en:n,photo:d.dataset.photo,temp:21,target:21,humidity:46,lights:[false],labels:['Światło główne'],kind:'bulb'})}save();d.close();render();toast(t('saved'))}if(a==='remove'&&r&&state.rooms.length>1){if(confirm(loc(`Usunąć „${r.name}” z tego demo? Nie dotyczy urządzeń ani konfiguracji HA.`,`Remove “${r.en||r.name}” from this demo? HA devices and configuration are unaffected.`))){state.rooms=state.rooms.filter(x=>x.id!==id);save();render();toast(t('saved'))}}});
document.addEventListener('input',e=>{if(e.target.id==='auto-search'){filter=e.target.value;document.querySelector('#auto-list').innerHTML=autoList()}if(e.target.id==='brightness'){const r=state.rooms.find(x=>x.id===e.target.dataset.room);if(r){r.brightness=+e.target.value;document.querySelector('#brightness-value').textContent=`${r.brightness}%`;save()}}});
document.addEventListener('change',e=>{if(e.target.dataset.field){const r=state.rooms.find(x=>x.id===e.target.dataset.room);if(r){r[e.target.dataset.field]=e.target.value;save();toast(t('saved'))}}});
document.querySelector('#reset').addEventListener('click',demoReset);
document.querySelector('#theme-shortcut').addEventListener('click',()=>{state.theme=light()?'dark':'light';save();render()});
window.addEventListener('hashchange',readRoute);
const clock=()=>document.querySelector('#clock').textContent=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});clock();setInterval(clock,30000);readRoute();
